const API='https://api.gains.trade/v1/arbitrum',WS='wss://api.gains.trade/v1/arbitrum/ws';
const featured=['BTC/USD','ETH/USD','SOL/USD','DOGE/USD','EUR/USD','NVDA/USD','AAPL/USD','TSLA/USD','SPY/USD','XAU/USD'];
const labels={crypto:'رمزارز',forex:'فارکس',stocks:'سهام',indices:'شاخص',commodities:'کالا'};
const icons={BTC:'₿',ETH:'Ξ',SOL:'◎',DOGE:'Ð',EUR:'€',GBP:'£',JPY:'¥',XAU:'Au',XAG:'Ag',NVDA:'N',AAPL:'●',TSLA:'T',SPY:'S'};
let markets=[],prices=new Map(),histories=new Map(),pendingHistories=new Set(),category='featured',search='',view='list',socket=null,seq=null,retryTimer=null,pollTimer=null,retryCount=0,started=false,latestReceive=0,streamLive=false,lastError=false,drawTimer=null,historyQueue=[],historyBusy=0,chartRequest=0,bootPromise=null;
const rows=document.querySelector('#live-rows'),status=document.querySelector('#market-status'),select=document.querySelector('#chart-symbol');
const formatPrice=(n,p=4)=>Number(n).toLocaleString('en-US',{minimumFractionDigits:Math.min(2,p),maximumFractionDigits:p});
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
async function get(path){const r=await fetch(API+path,{signal:AbortSignal.timeout(12000)});if(!r.ok)throw new Error('HTTP '+r.status);const j=await r.json();if(!Array.isArray(j.data))throw new Error('Invalid data');return j.data}
function visible(){let list=category==='featured'?featured.map(s=>markets.find(m=>m.symbol===s)).filter(Boolean):markets.filter(m=>m.group===category);if(search)list=list.filter(m=>(m.symbol+' '+m.base).toLowerCase().includes(search));return list.slice(0,category==='featured'?10:15)}
function usablePrice(p){return p&&Number.isFinite(Number(p.mark))&&Number(p.mark)>0&&Number.isFinite(Number(p.updatedAt))}
function updatePrices(items){let changed=false;for(const p of items){if(!p||typeof p.market!=='string'||!usablePrice(p))continue;const old=prices.get(p.market);if(old&&Number(old.updatedAt)>Number(p.updatedAt))continue;prices.set(p.market,{...p,direction:old?Math.sign(Number(p.mark)-Number(old.mark)):0,tickAt:old&&Number(p.mark)!==Number(old.mark)?Date.now():old?.tickAt||0});changed=true}if(changed){latestReceive=Date.now();lastError=false;scheduleRender()}}
function scheduleRender(){if(drawTimer)return;drawTimer=setTimeout(()=>{drawTimer=null;render()},900)}
function state(){status.className='data-status';if(lastError&&!prices.size){status.textContent='دریافت داده ممکن نشد';status.classList.add('error')}else if(!markets.length){status.textContent='در حال دریافت بازارها'}else if(!prices.size){status.textContent='در انتظار قیمت‌ها'}else{const fresh=visible().some(m=>{const p=prices.get(m.symbol);return usablePrice(p)&&Date.now()-Number(p.updatedAt)<90000});if(streamLive&&fresh&&Date.now()-latestReceive<30000){status.textContent='جریان قیمت متصل';status.classList.add('live')}else if(lastError){status.textContent='ارتباط قطع؛ آخرین دادهٔ دریافتی';status.classList.add('error')}else if(!fresh){status.textContent='آخرین داده؛ برخی قیمت‌ها قدیمی‌اند'}else status.textContent='آخرین قیمت‌های دریافتی'}const indicator=document.createElement('i');status.prepend(indicator);document.querySelector('#last-update').textContent=latestReceive?'آخرین دریافت '+new Intl.DateTimeFormat('fa-IR',{hour:'2-digit',minute:'2-digit',second:'2-digit',timeZone:'Asia/Dubai'}).format(latestReceive):'منتظر دریافت داده'}
function dayChange(m,p){const h=histories.get(m.symbol);if(!usablePrice(p)||!h?.length)return null;const target=Number(p.updatedAt)-86400000;const base=h.filter(c=>Number(c.time)<=target).at(-1);if(!base||target-Number(base.time)>3600000||!Number.isFinite(Number(base.close))||Number(base.close)<=0)return null;return (Number(p.mark)/Number(base.close)-1)*100}
function render(){state();const list=visible();if(!list.length){rows.innerHTML=`<tr><td colspan="7" class="market-empty">${markets.length?'نمادی با این عبارت پیدا نشد.':lastError?'ارتباط با منبع برقرار نشد. از دکمهٔ تازه‌سازی دوباره تلاش کنید.':'در حال دریافت اطلاعات بازار…'}</td></tr>`;return}
rows.innerHTML=list.map(m=>{const last=histories.get(m.symbol)?.at(-1),direct=prices.get(m.symbol),p=usablePrice(direct)?direct:last?{mark:last.close,updatedAt:Number(last.time)+3600000,direction:0,tickAt:0}:null,valid=usablePrice(p),stale=valid&&Date.now()-Number(p.updatedAt)>90000,delta=dayChange(m,p),freshTick=valid&&Date.now()-p.tickAt<1800,precision=Math.max(0,Math.min(8,Number(m.pricePrecision)||0));return `<tr><td><span class="market-symbol"><span class="coin-icon ${m.base==='BTC'?'btc':m.base==='ETH'?'eth':''}" aria-hidden="true">${esc(icons[m.base]||m.base.slice(0,1))}</span><span dir="ltr"><b>${esc(m.base)}</b><small>/${esc(m.quote)}</small></span></span></td><td>${esc(labels[m.group]||m.group)}</td><td><span class="numeric price-cell ${freshTick?(p.direction>0?'tick-up':p.direction<0?'tick-down':''):''}">${valid?formatPrice(p.mark,precision):'—'}</span></td><td>${delta===null?'<span class="numeric">—</span>':`<span class="numeric change ${delta>=0?'positive':'negative'}">${delta>0?'+':''}${delta.toFixed(2)}%</span>`}</td><td><span class="numeric">${esc(m.maxLeverage)}×</span></td><td><span class="numeric">${Number.isFinite(Number(m.spreadRate))?(Number(m.spreadRate)*100).toFixed(3).replace(/0$/,'')+'%':'—'}</span></td><td><span class="pair-status ${stale?'old':''}" title="${valid?new Date(Number(p.updatedAt)).toISOString():''}">${!m.isOpen?'بازار بسته':!valid?'در انتظار قیمت':stale?'قیمت قدیمی':'باز'}</span></td></tr>`}).join('');
const old=select.value,options=list.map(m=>`<option value="${esc(m.symbol)}">${esc(m.symbol)}</option>`).join('');if(select.innerHTML!==options){select.innerHTML=options;if(list.some(m=>m.symbol===old))select.value=old;}for(const m of list)enqueueHistory(m.symbol);if(view==='chart')drawChart();}
function enqueueHistory(symbol){if(histories.has(symbol)||pendingHistories.has(symbol))return;pendingHistories.add(symbol);historyQueue.push(symbol);pumpHistory()}
async function pumpHistory(){while(historyBusy<3&&historyQueue.length){const symbol=historyQueue.shift();historyBusy++;const now=Date.now();get('/markets/'+symbol.replace('/','-')+'/candles?interval=1h&from='+(now-27*3600000)+'&to='+now).then(data=>{const valid=data.filter(c=>Number.isFinite(Number(c.time))&&Number.isFinite(Number(c.close))&&Number(c.close)>0).sort((a,b)=>Number(a.time)-Number(b.time));histories.set(symbol,valid)}).catch(()=>{histories.set(symbol,[])}).finally(()=>{historyBusy--;pendingHistories.delete(symbol);scheduleRender();pumpHistory()})}}
function drawChart(){const id=++chartRequest,symbol=select.value,el=document.querySelector('#chart-content'),h=histories.get(symbol);if(!symbol){el.textContent='نمادی برای نمایش وجود ندارد.';return}if(!h){el.textContent='در حال دریافت نمودار…';enqueueHistory(symbol);return}if(h.length<2){el.textContent='تاریخچهٔ معتبر برای این نماد در دسترس نیست.';return}if(id!==chartRequest)return;const values=h.map(c=>Number(c.close)),min=Math.min(...values),max=Math.max(...values),range=max-min||Math.abs(max)*.001||1;const d=values.map((v,i)=>(i?'L':'M')+(i/(values.length-1)*1000).toFixed(2)+' '+(190-(v-min)/range*165).toFixed(2)).join(' ');el.innerHTML=`<span class="chart-values" dir="ltr">${esc(symbol)} · ${formatPrice(values.at(-1),markets.find(m=>m.symbol===symbol)?.pricePrecision||4)}</span><svg viewBox="0 0 1000 210" role="img" aria-label="روند واقعی قیمت ${esc(symbol)} در ۲۴ ساعت اخیر" preserveAspectRatio="none"><defs><linearGradient id="market-fill" x1="0" x2="0" y1="0" y2="1"><stop stop-color="#82e7bd" stop-opacity=".15"/><stop offset="1" stop-color="#82e7bd" stop-opacity="0"/></linearGradient></defs><path d="M0 45H1000M0 100H1000M0 155H1000M0 210H1000" stroke="#ffffff0e" fill="none"/><path d="${d}L1000 210H0Z" fill="url(#market-fill)"/><path d="${d}" fill="none" stroke="#82e7bd" stroke-width="1.7" vector-effect="non-scaling-stroke"/></svg>`}
function connect(){if(document.hidden||!started||socket&&(socket.readyState===0||socket.readyState===1))return;socket=new WebSocket(WS);socket.onopen=()=>{seq=null;socket.send(JSON.stringify({op:'subscribe',channel:'prices'}));retryCount=0};socket.onmessage=e=>{try{const msg=JSON.parse(e.data);if(msg.op==='ping'){socket.send(JSON.stringify({op:'pong'}));return}if(msg.channel==='prices'&&Array.isArray(msg.data)){if(!msg.snapshot&&seq!==null&&Number.isFinite(msg.seq)&&msg.seq!==seq+1){seq=null;socket.send(JSON.stringify({op:'unsubscribe',channel:'prices'}));socket.send(JSON.stringify({op:'subscribe',channel:'prices'}));return}seq=Number.isFinite(msg.seq)?msg.seq:null;streamLive=true;updatePrices(msg.data);if(pollTimer){clearInterval(pollTimer);pollTimer=null}}}catch{}};socket.onerror=()=>{lastError=true;state()};socket.onclose=()=>{socket=null;streamLive=false;state();if(!started||document.hidden)return;startPolling();retryTimer=setTimeout(connect,Math.min(30000,2000*2**Math.min(retryCount++,4)))};}
async function fetchPrices(){try{const data=await get('/prices');updatePrices(data)}catch{lastError=true;render()}}
function startPolling(){if(pollTimer)return;pollTimer=setInterval(()=>{if(!document.hidden)fetchPrices()},30000)}
async function boot(){if(bootPromise)return bootPromise;bootPromise=(async()=>{started=true;lastError=false;state();try{const data=await get('/markets');markets=data.filter(m=>m&&typeof m.symbol==='string'&&typeof m.base==='string');await fetchPrices();render();connect()}catch{lastError=true;render()}})().finally(()=>bootPromise=null);return bootPromise}
document.querySelectorAll('[data-category]').forEach(b=>b.addEventListener('click',()=>{category=b.dataset.category;document.querySelectorAll('[data-category]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b))});render()}));document.querySelector('#market-search').addEventListener('input',e=>{search=e.target.value.trim().toLowerCase();render()});document.querySelectorAll('[data-view]').forEach(b=>b.addEventListener('click',()=>{view=b.dataset.view;document.querySelectorAll('[data-view]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b))});document.querySelector('#market-list').hidden=view!=='list';document.querySelector('#market-chart').hidden=view!=='chart';if(view==='chart')drawChart()}));select.addEventListener('change',drawChart);document.querySelector('#refresh-market').addEventListener('click',()=>{if(!markets.length)boot();else{histories.clear();fetchPrices();connect();render()}});
document.addEventListener('visibilitychange',()=>{if(document.hidden){clearTimeout(retryTimer);if(socket)socket.close();if(pollTimer){clearInterval(pollTimer);pollTimer=null}}else if(started){fetchPrices();connect()}});window.addEventListener('pagehide',()=>{started=false;clearTimeout(retryTimer);clearInterval(pollTimer);if(socket)socket.close()});setInterval(()=>{if(started&&!document.hidden)state()},5000);setInterval(()=>{if(started&&!document.hidden){histories.clear();for(const m of visible())enqueueHistory(m.symbol)}},300000);
new IntersectionObserver((entries,observer)=>{if(entries.some(e=>e.isIntersecting)){boot();observer.disconnect()}},{rootMargin:'500px'}).observe(document.querySelector('#markets'));
